  1→import {
  2→  afterNextRender,
  3→  ChangeDetectionStrategy,
  4→  Component,
  5→  ElementRef,
  6→  NgZone,
  7→  OnDestroy,
  8→  viewChild,
  9→} from "@angular/core";
 10→import * as THREE from "three";
 11→import {
 12→  createLightning,
 13→  disposeLightning,
 14→  Lightning,
 15→  LIGHTNING_INTERVAL,
 16→  updateLightning,
 17→} from "./sea-lightning";
 18→import { waveY } from "./sea-signals";
 19→
 20→@Component({
 21→  selector: "tfc-sea-backdrop",
 22→  changeDetection: ChangeDetectionStrategy.OnPush,
 23→  styles: [
 24→    `
 25→      :host {
 26→        display: block;
 27→        position: absolute;
 28→        inset: 0;
 29→        pointer-events: none;
 30→        overflow: hidden;
 31→      }
 32→
 33→      canvas {
 34→        display: block;
 35→        width: 100%;
 36→        height: 100%;
 37→      }
 38→    `,
 39→  ],
 40→  template: `<canvas #canvas></canvas>`,
 41→})
 42→export class SeaBackdrop implements OnDestroy {
 43→  private readonly canvasRef =
 44→    viewChild.required<ElementRef<HTMLCanvasElement>>("canvas");
 45→  private renderer!: THREE.WebGLRenderer;
 46→  private scene!: THREE.Scene;
 47→  private camera!: THREE.PerspectiveCamera;
 48→  private plane!: THREE.Mesh<THREE.PlaneGeometry, THREE.MeshBasicMaterial>;
 49→  private animationId = 0;
 50→  private resizeObserver!: ResizeObserver;
 51→
 52→  private lightnings: Lightning[] = [];
 53→  private nextLightning = 1;
 54→
 55→  private get themeColor(): THREE.Color {
 56→    const raw = getComputedStyle(document.documentElement)
 57→      .getPropertyValue("--color-primary")
 58→      .trim();
 59→    return new THREE.Color(
 60→      raw.startsWith("oklch") ? 0x1ac5c5 : raw || 0x1ac5c5,
 61→    );
 62→  }
 63→
 64→  constructor(private ngZone: NgZone) {
 65→    afterNextRender(() => {
 66→      this.initScene();
 67→      this.ngZone.runOutsideAngular(() => this.animate(0));
 68→    });
 69→  }
 70→
 71→  ngOnDestroy(): void {
 72→    cancelAnimationFrame(this.animationId);
 73→    this.resizeObserver?.disconnect();
 74→    this.renderer?.dispose();
 75→    this.plane?.geometry.dispose();
 76→    this.plane?.material.dispose();
 77→    for (const l of this.lightnings) {
 78→      disposeLightning(this.scene, l);
 79→    }
 80→  }
 81→
 82→  private initScene(): void {
 83→    const canvas = this.canvasRef().nativeElement;
 84→    const w = canvas.clientWidth || 1;
 85→    const h = canvas.clientHeight || 1;
 86→
 87→    this.renderer = new THREE.WebGLRenderer({
 88→      canvas,
 89→      alpha: true,
 90→      antialias: true,
 91→    });
 92→    this.renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
 93→    this.renderer.setSize(w, h, false);
 94→
 95→    const bgColor = new THREE.Color(0x061218);
 96→    this.scene = new THREE.Scene();
 97→    this.scene.background = bgColor;
 98→    this.camera = new THREE.PerspectiveCamera(27, w / h, 0.1, 100);
 99→    this.camera.position.set(0, 5, 5);
100→    this.camera.lookAt(0, -0.3, 0);
101→
102→    this.scene.add(new THREE.AmbientLight(0xffffff, 0.5));
103→    const dir = new THREE.DirectionalLight(0xffffff, 0.8);
104→    dir.position.set(-3, 5, 4);
105→    this.scene.add(dir);
106→
107→    const primary = this.themeColor;
108→    const pl1 = new THREE.PointLight(primary, 2.5, 20);
109→    pl1.position.set(0, 2, 3);
110→    const pl2 = new THREE.PointLight(primary, 1.5, 15);
111→    pl2.position.set(-4, 1, -2);
112→    this.scene.add(pl1, pl2);
113→
114→    const geo = new THREE.PlaneGeometry(24, 14, 180, 120);
115→    geo.rotateX(-Math.PI / 2);
116→    const mat = new THREE.MeshBasicMaterial({
117→      color: primary,
118→      wireframe: true,
119→      transparent: true,
120→      opacity: 0.08,
121→    });
122→    this.plane = new THREE.Mesh(geo, mat);
123→    this.plane.position.y = -0.3;
124→    this.scene.add(this.plane);
125→
126→    this.scene.fog = new THREE.Fog(bgColor, 8, 16);
127→    this.resizeObserver = new ResizeObserver(() => this.handleResize());
128→    this.resizeObserver.observe(canvas);
129→  }
130→
131→  // ── Lightning bolts ─────────────────────────────────────
132→
133→  private updateLightnings(t: number): void {
134→    if (t >= this.nextLightning) {
135→      this.lightnings.push(
136→        createLightning(this.scene, this.plane.geometry, t),
137→      );
138→      this.nextLightning =
139→        t + LIGHTNING_INTERVAL + (Math.random() - 0.5) * 2;
140→    }
141→    for (let i = this.lightnings.length - 1; i >= 0; i--) {
142→      if (!updateLightning(this.lightnings[i], t)) {
143→        disposeLightning(this.scene, this.lightnings[i]);
144→        this.lightnings.splice(i, 1);
145→      }
146→    }
147→  }
148→
149→  // ── Core loop ──────────────────────────────────────────
150→
151→  private handleResize(): void {
152→    const canvas = this.canvasRef().nativeElement;
153→    const w = canvas.clientWidth;
154→    const h = canvas.clientHeight;
155→    this.camera.aspect = w / h;
156→    this.camera.updateProjectionMatrix();
157→    this.renderer.setSize(w, h, false);
158→  }
159→
160→  private animate(time: number): void {
161→    this.animationId = requestAnimationFrame((t) => this.animate(t));
162→
163→    const t = time * 0.001;
164→    const positions = this.plane.geometry.attributes["position"];
165→    const count = positions.count;
166→
167→    for (let i = 0; i < count; i++) {
168→      const x = positions.getX(i);
169→      const z = positions.getZ(i);
170→      positions.setY(i, waveY(x, z, t));
171→    }
172→
173→    positions.needsUpdate = true;
174→    this.plane.geometry.computeVertexNormals();
175→
176→    this.updateLightnings(t);
177→    this.renderer.render(this.scene, this.camera);
178→  }
179→}
