  1→import * as THREE from "three";
  2→import { createGlowTexture, waveY } from "./sea-signals";
  3→
  4→/** How often a new lightning bolt spawns (seconds). */
  5→export const LIGHTNING_INTERVAL = 0.8;
  6→
  7→/** How long the trail lingers after the head passes (seconds). */
  8→const TRAIL_FADE = 1.5;
  9→/** Slow global fade-out after trail is done (seconds). */
 10→const GLOBAL_FADE = 3.0;
 11→/** Speed: waypoints per second the head travels. */
 12→const TRAVEL_SPEED = 150;
 13→/** Max edges to walk along the wireframe. */
 14→const PATH_EDGES = 400;
 15→
 16→const BOLT_COLOR = 0xe84057; // hostile red — supply-chain attack
 17→const BOLT_COLOR_THREE = new THREE.Color(BOLT_COLOR);
 18→
 19→export interface Lightning {
 20→  birth: number;
 21→  line: THREE.Line;
 22→  head: THREE.Sprite;
 23→  headLight: THREE.PointLight;
 24→  waypoints: { x: number; z: number }[];
 25→}
 26→
 27→/** Grid-edge neighbours: 4 cardinal + 4 diagonal (follow wireframe lines). */
 28→const EDGE_DIRS: [number, number][] = [
 29→  [1, 0], [-1, 0], [0, 1], [0, -1],
 30→  [1, 1], [1, -1], [-1, 1], [-1, -1],
 31→];
 32→
 33→function tracePath(
 34→  positions: THREE.BufferAttribute,
 35→  cols: number,
 36→  rows: number,
 37→): { x: number; z: number }[] {
 38→  const path: { x: number; z: number }[] = [];
 39→  const visited = new Set<number>();
 40→  const key = (c: number, r: number) => r * cols + c;
 41→
 42→  // All 8 directions for varied bolt angles
 43→  const [headCol, headRow] = EDGE_DIRS[Math.floor(Math.random() * EDGE_DIRS.length)];
 44→
 45→  // Start at the opposite edge so the bolt traverses the sea
 46→  let col: number, row: number;
 47→  if (headCol > 0) col = 0;
 48→  else if (headCol < 0) col = cols - 1;
 49→  else col = Math.floor(Math.random() * cols);
 50→  if (headRow > 0) row = 0;
 51→  else if (headRow < 0) row = rows - 1;
 52→  else row = Math.floor(Math.random() * rows);
 53→
 54→  visited.add(key(col, row));
 55→  path.push({ x: positions.getX(key(col, row)), z: positions.getZ(key(col, row)) });
 56→
 57→  for (let i = 0; i < PATH_EDGES; i++) {
 58→    let moved = false;
 59→
 60→    if (Math.random() < 0.6) {
 61→      const fc = col + headCol;
 62→      const fr = row + headRow;
 63→      if (fc >= 0 && fc < cols && fr >= 0 && fr < rows && !visited.has(key(fc, fr))) {
 64→        col = fc;
 65→        row = fr;
 66→        moved = true;
 67→      }
 68→    }
 69→
 70→    if (!moved) {
 71→      const shuffled = [...EDGE_DIRS].sort(() => Math.random() - 0.5);
 72→      for (const [dc, dr] of shuffled) {
 73→        const nc = col + dc;
 74→        const nr = row + dr;
 75→        if (nc >= 0 && nc < cols && nr >= 0 && nr < rows && !visited.has(key(nc, nr))) {
 76→          col = nc;
 77→          row = nr;
 78→          moved = true;
 79→          break;
 80→        }
 81→      }
 82→    }
 83→
 84→    if (!moved) break;
 85→
 86→    visited.add(key(col, row));
 87→    const vi = key(col, row);
 88→    path.push({ x: positions.getX(vi), z: positions.getZ(vi) });
 89→
 90→    if ((headCol === 1 && col >= cols - 2) ||
 91→        (headCol === -1 && col <= 1) ||
 92→        (headRow === 1 && row >= rows - 2) ||
 93→        (headRow === -1 && row <= 1)) {
 94→      break;
 95→    }
 96→  }
 97→
 98→  return path;
 99→}
100→
101→let sharedGlow: THREE.Texture | null = null;
102→
103→export function createLightning(
104→  scene: THREE.Scene,
105→  planeGeo: THREE.PlaneGeometry,
106→  t: number,
107→): Lightning {
108→  const params = planeGeo.parameters;
109→  const cols = params.widthSegments + 1;
110→  const rows = params.heightSegments + 1;
111→  const positions = planeGeo.attributes["position"] as THREE.BufferAttribute;
112→  const waypoints = tracePath(positions, cols, rows);
113→  const n = waypoints.length;
114→
115→  // Position buffer
116→  const verts = new Float32Array(n * 3);
117→  // Per-vertex color buffer (for trail fade)
118→  const colors = new Float32Array(n * 3);
119→  for (let i = 0; i < n; i++) {
120→    const wp = waypoints[i];
121→    const off = i * 3;
122→    verts[off] = wp.x;
123→    verts[off + 1] = waveY(wp.x, wp.z, t);
124→    verts[off + 2] = wp.z;
125→    colors[off] = 0;
126→    colors[off + 1] = 0;
127→    colors[off + 2] = 0;
128→  }
129→
130→  const geo = new THREE.BufferGeometry();
131→  geo.setAttribute("position", new THREE.BufferAttribute(verts, 3));
132→  geo.setAttribute("color", new THREE.BufferAttribute(colors, 3));
133→
134→  const mat = new THREE.LineBasicMaterial({
135→    vertexColors: true,
136→    transparent: true,
137→    opacity: 1,
138→    blending: THREE.AdditiveBlending,
139→    depthWrite: false,
140→  });
141→
142→  const line = new THREE.Line(geo, mat);
143→  line.position.y = -0.3;
144→  scene.add(line);
145→
146→  // Travelling glow sprite
147→  if (!sharedGlow) sharedGlow = createGlowTexture();
148→  const spriteMat = new THREE.SpriteMaterial({
149→    map: sharedGlow,
150→    color: BOLT_COLOR,
151→    transparent: true,
152→    opacity: 0,
153→    blending: THREE.AdditiveBlending,
154→    depthWrite: false,
155→  });
156→  const head = new THREE.Sprite(spriteMat);
157→  head.scale.set(0.4, 0.4, 1);
158→  const wp0 = waypoints[0];
159→  head.position.set(wp0.x, waveY(wp0.x, wp0.z, t) - 0.3 + 0.15, wp0.z);
160→  scene.add(head);
161→
162→  // Point light follows the head
163→  const headLight = new THREE.PointLight(BOLT_COLOR, 0, 4);
164→  headLight.position.copy(head.position);
165→  scene.add(headLight);
166→
167→  return { birth: t, line, head, headLight, waypoints };
168→}
169→
170→/** Returns false when the bolt has fully faded. */
171→export function updateLightning(l: Lightning, t: number): boolean {
172→  const age = t - l.birth;
173→  const n = l.waypoints.length;
174→  const travelDuration = n / TRAVEL_SPEED;
175→  const totalLife = travelDuration + TRAIL_FADE + GLOBAL_FADE;
176→
177→  if (age > totalLife) return false;
178→
179→  // Global opacity: full during travel+trail, then slowly fade entire bolt
180→  const globalFadeStart = travelDuration + TRAIL_FADE;
181→  const globalOpacity = age > globalFadeStart
182→    ? Math.max(0, 1 - (age - globalFadeStart) / GLOBAL_FADE)
183→    : 1;
184→
185→  // Current head position (fractional index into waypoints)
186→  const headIdx = Math.min(age * TRAVEL_SPEED, n - 1);
187→  const headI = Math.floor(headIdx);
188→
189→  // Update positions to ride the wave
190→  const posBuf = l.line.geometry.attributes["position"] as THREE.BufferAttribute;
191→  for (let i = 0; i < n; i++) {
192→    const wp = l.waypoints[i];
193→    const off = i * 3;
194→    posBuf.array[off] = wp.x;
195→    posBuf.array[off + 1] = waveY(wp.x, wp.z, t);
196→    posBuf.array[off + 2] = wp.z;
197→  }
198→  posBuf.needsUpdate = true;
199→
200→  // Update per-vertex colors: bright at head, fading trail behind
201→  const colBuf = l.line.geometry.attributes["color"] as THREE.BufferAttribute;
202→  const r = BOLT_COLOR_THREE.r;
203→  const g = BOLT_COLOR_THREE.g;
204→  const b = BOLT_COLOR_THREE.b;
205→
206→  for (let i = 0; i < n; i++) {
207→    const off = i * 3;
208→    if (i > headI) {
209→      // Ahead of head — invisible
210→      colBuf.array[off] = 0;
211→      colBuf.array[off + 1] = 0;
212→      colBuf.array[off + 2] = 0;
213→    } else {
214→      // Behind head — fade based on distance from head
215→      const dist = headI - i;
216→      const timeSincePassed = dist / TRAVEL_SPEED;
217→      const fade = Math.max(0, 1 - timeSincePassed / TRAIL_FADE);
218→      const brightness = fade * globalOpacity;
219→      colBuf.array[off] = r * brightness;
220→      colBuf.array[off + 1] = g * brightness;
221→      colBuf.array[off + 2] = b * brightness;
222→    }
223→  }
224→  colBuf.needsUpdate = true;
225→
226→  // Move head sprite + light
227→  const wp = l.waypoints[headI];
228→  const hy = waveY(wp.x, wp.z, t) - 0.3 + 0.15;
229→  l.head.position.set(wp.x, hy, wp.z);
230→  l.headLight.position.set(wp.x, hy, wp.z);
231→
232→  // Head brightness: full while travelling, fade after done
233→  const headAlive = age < travelDuration;
234→  const headOpacity = (headAlive ? 0.4 : Math.max(0, 1 - (age - travelDuration) / TRAIL_FADE) * 0.2) * globalOpacity;
235→  (l.head.material as THREE.SpriteMaterial).opacity = headOpacity;
236→  l.headLight.intensity = (headAlive ? 2 : headOpacity * 2) * globalOpacity;
237→
238→  return true;
239→}
240→
241→export function disposeLightning(scene: THREE.Scene, l: Lightning): void {
242→  scene.remove(l.line);
243→  l.line.geometry.dispose();
244→  (l.line.material as THREE.Material).dispose();
245→  scene.remove(l.head);
246→  (l.head.material as THREE.SpriteMaterial).dispose();
247→  scene.remove(l.headLight);
248→}
