218→
219→  protected onStop(): void {
220→    this.api.stop(this.exerciseId()).subscribe({
221→      next: () => this.onExerciseStopped(),
222→    });
223→  }
224→
225→  protected onExerciseStopped(): void {
226→    this.ws.disconnect();
227→    this.router.navigate(["/"]);
228→  }
229→
230→  ngOnDestroy(): void {
231→    this.tick.stop();
232→    this.ws.disconnect();
233→    this.sub?.unsubscribe();
234→    this.connSub?.unsubscribe();
235→  }
236→  protected onRoleCardSubmitted(submission: RoleCardSubmission): void {
237→    const decision = this.activeDecisions()[0];
238→    if (!decision) return;
239→    const role = this.store
240→      .context()
241→      ?.roles?.find((r) => r.id === submission.roleId);
242→    if (role?.player_type === "decision_maker") {
243→      submitDecision(
244→        this.decisionApi,
245→        this.store,
246→        this.exerciseId(),
247→        decision,
248→        submission,
249→      );
250→    } else {
251→      submitRoleRecommendation(
252→        this.decisionApi,
253→        this.exerciseId(),
254→        decision,
255→        this.participantId(),
256→        {
257→          roleId: submission.roleId,
258→          selectedOptions: submission.selectedOptions,
259→          freeText: submission.freeText,
260→        },
261→      );
262→    }
263→    const updated = new Set(this.submittedRoles());
264→    updated.add(submission.roleId);
265→    this.submittedRoles.set(updated);
266→  }
267→}
