  1→import * as THREE from "three";
  2→import { waveY } from "./sea-signals";
  3→
  4→const GLOW_DURATION = 1.5;
  5→const EXPLODE_DURATION = 3;
  6→const LIFESPAN = GLOW_DURATION + EXPLODE_DURATION;
  7→const HALO_MAX_RADIUS = 3.5;
  8→
  9→export const CONVERGENCE_INTERVAL = 4;
 10→
 11→export interface Convergence {
 12→  x: number;
 13→  z: number;
 14→  birth: number;
 15→  dot: THREE.Sprite;
 16→  dotLight: THREE.PointLight;
 17→  halo: THREE.Mesh<THREE.SphereGeometry, THREE.MeshBasicMaterial>;
 18→}
 19→
 20→/** Pick a random vertex from the plane grid. */
 21→function pickVertex(geo: THREE.PlaneGeometry): { x: number; z: number } {
 22→  const pos = geo.attributes["position"];
 23→  const idx = Math.floor(Math.random() * pos.count);
 24→  return { x: pos.getX(idx), z: pos.getZ(idx) };
 25→}
 26→
 27→export function createConvergence(
 28→  scene: THREE.Scene,
 29→  glowTexture: THREE.Texture,
 30→  themeColor: THREE.Color,
 31→  planeGeo: THREE.PlaneGeometry,
 32→  t: number,
 33→): Convergence {
 34→  const { x, z } = pickVertex(planeGeo);
 35→  const y = waveY(x, z, t);
 36→
 37→  const dotMat = new THREE.SpriteMaterial({
 38→    map: glowTexture,
 39→    color: 0xffffff,
 40→    transparent: true,
 41→    opacity: 0,
 42→    blending: THREE.AdditiveBlending,
 43→    depthWrite: false,
 44→  });
 45→  const dot = new THREE.Sprite(dotMat);
 46→  dot.position.set(x, y, z);
 47→  dot.scale.set(0.1, 0.1, 1);
 48→  scene.add(dot);
 49→
 50→  const dotLight = new THREE.PointLight(0xffffff, 0, 8);
 51→  dotLight.position.set(x, y, z);
 52→  scene.add(dotLight);
 53→
 54→  const haloGeo = new THREE.SphereGeometry(1, 20, 14);
 55→  const haloMat = new THREE.MeshBasicMaterial({
 56→    color: themeColor,
 57→    transparent: true,
 58→    opacity: 0,
 59→    blending: THREE.AdditiveBlending,
 60→    depthWrite: false,
 61→    side: THREE.BackSide,
 62→    wireframe: true,
 63→  });
 64→  const halo = new THREE.Mesh(haloGeo, haloMat);
 65→  halo.position.set(x, y, z);
 66→  halo.scale.set(0.01, 0.01, 0.01);
 67→  scene.add(halo);
 68→
 69→  return { x, z, birth: t, dot, dotLight, halo };
 70→}
 71→
 72→/** Returns false when the convergence has expired and should be removed. */
 73→export function updateConvergence(c: Convergence, t: number): boolean {
 74→  const age = t - c.birth;
 75→  if (age > LIFESPAN) return false;
 76→
 77→  const y = waveY(c.x, c.z, t);
 78→  c.dot.position.y = y;
 79→  c.dotLight.position.y = y;
 80→  c.halo.position.y = y;
 81→
 82→  if (age < GLOW_DURATION) {
 83→    const glow = (age / GLOW_DURATION) ** 2;
 84→    (c.dot.material as THREE.SpriteMaterial).opacity = glow * 0.95;
 85→    c.dot.scale.setScalar(0.2 + glow * 0.7);
 86→    c.dotLight.intensity = glow * 6;
 87→    return true;
 88→  }
 89→
 90→  const ep = (age - GLOW_DURATION) / EXPLODE_DURATION;
 91→  const eased = 1 - (1 - ep) ** 2;
 92→
 93→  const scale = eased * HALO_MAX_RADIUS;
 94→  c.halo.scale.set(scale, scale, scale);
 95→  c.halo.material.opacity = (1 - eased) * 0.45;
 96→
 97→  const dotFade = 1 - ep;
 98→  (c.dot.material as THREE.SpriteMaterial).opacity = dotFade * 0.95;
 99→  c.dot.scale.setScalar(0.9 * dotFade);
100→  c.dotLight.intensity = dotFade * 6;
101→
102→  return true;
103→}
104→
105→export function disposeConvergence(scene: THREE.Scene, c: Convergence): void {
106→  scene.remove(c.dot);
107→  (c.dot.material as THREE.SpriteMaterial).dispose();
108→  scene.remove(c.dotLight);
109→  scene.remove(c.halo);
110→  c.halo.geometry.dispose();
111→  c.halo.material.dispose();
112→}
