 42→export const ScenarioBuilderStore = signalStore(
 43→  withState<ScenarioBuilderState>({
 44→    scenarioId: null,
 45→    title: "",
 46→    description: "",
 47→    content: emptyContent,
 48→    saving: false,
 49→    error: null,
 50→    loadedSnapshot: null,
