 52→
 53→  withMethods((store) => ({
 54→    loadScenario(
 55→      id: number,
 56→      title: string,
 57→      description: string,
 58→      content: ScenarioContent | null,
 59→    ): void {
 60→      const c = content ?? emptyContent;
 61→      const snapshot = JSON.stringify({ title, description, content: c });
 62→      patchState(store, {
 63→        scenarioId: id,
 64→        title,
 65→        description,
 66→        content: c,
 67→        loadedSnapshot: snapshot,
 68→      });
 69→    },
 70→
 71→    loadImport(
 72→      title: string,
 73→      description: string,
