197→export class ScenarioSetupTabComponent implements OnInit {
198→  protected readonly store = inject(ScenarioBuilderStore);
199→  private readonly domainConfigApi = inject(DomainConfigApiService);
200→
201→  protected readonly domainConfig = signal<DomainConfigResponse | null>(null);
202→
203→  protected readonly objectives = computed(
204→    () => this.store.content().objectives ?? [],
205→  );
206→  protected readonly rules = computed(
207→    () => this.store.content().rules ?? [],
208→  );
209→  protected readonly gameMode = computed(
210→    () => this.store.content().game_mode ?? "classic",
211→  );
212→  protected readonly thresholdLo = computed(
213→    () => this.store.content().score_tier_thresholds?.["lo"] ?? 0,
214→  );
215→  protected readonly thresholdMid = computed(
216→    () => this.store.content().score_tier_thresholds?.["mid"] ?? 0,
217→  );
218→
219→  ngOnInit(): void {
220→    this.domainConfigApi.getBySlug("silent-wake").subscribe({
221→      next: (config) => this.domainConfig.set(config),
222→    });
223→  }
224→
225→  protected onBriefingChange(event: Event): void {
226→    const target = event.target;
227→    if (target instanceof HTMLTextAreaElement) {
228→      this.store.setBriefing(target.value);
229→    }
230→  }
231→
232→  protected addObjective(): void {
233→    this.store.setObjectives([...this.objectives(), ""]);
234→  }
235→
236→  protected removeObjective(index: number): void {
237→    this.store.setObjectives(this.objectives().filter((_, i) => i !== index));
238→  }
239→
240→  protected onObjectiveChange(index: number, event: Event): void {
241→    const target = event.target;
242→    if (!(target instanceof HTMLInputElement)) return;
243→    const updated = [...this.objectives()];
244→    updated[index] = target.value;
245→    this.store.setObjectives(updated);
246→  }
247→
248→  protected addRule(): void {
249→    this.store.setRules([...this.rules(), ""]);
250→  }
251→
252→  protected removeRule(index: number): void {
253→    this.store.setRules(this.rules().filter((_, i) => i !== index));
254→  }
255→
256→  protected onRuleChange(index: number, event: Event): void {
257→    const target = event.target;
258→    if (!(target instanceof HTMLInputElement)) return;
259→    const updated = [...this.rules()];
260→    updated[index] = target.value;
261→    this.store.setRules(updated);
262→  }
263→
264→  protected onThresholdLoChange(event: Event): void {
265→    const target = event.target;
266→    if (!(target instanceof HTMLInputElement)) return;
267→    const val = parseFloat(target.value);
268→    if (isNaN(val)) return;
269→    const current = this.store.content().score_tier_thresholds ?? {};
270→    this.store.setScoreTierThresholds({ ...current, lo: val });
271→  }
272→
273→  protected onThresholdMidChange(event: Event): void {
274→    const target = event.target;
275→    if (!(target instanceof HTMLInputElement)) return;
276→    const val = parseFloat(target.value);
277→    if (isNaN(val)) return;
278→    const current = this.store.content().score_tier_thresholds ?? {};
279→    this.store.setScoreTierThresholds({ ...current, mid: val });
280→  }
281→
282→  protected onTimeFactorChange(event: Event): void {
283→    const target = event.target;
284→    if (!(target instanceof HTMLInputElement)) return;
285→    const val = parseFloat(target.value);
286→    if (val > 0) this.store.setTimeFactor(val);
287→  }
288→}
