25→export class StressBarComponent {
26→  readonly stress = input(0);
27→
28→  protected readonly severity = computed(() => {
29→    const s = this.stress();
30→    if (s <= 3) return "low";
31→    if (s <= 6) return "medium";
32→    return "high";
33→  });
34→
